FUNCTION_BLOCK FB_FPSO_TurretSwivelSealingESD
(*
 ===================================================================================================
  LUMINA CYBER-PHYSICAL SYSTEMS ARCHITECTURE SPECIFICATION - IEC 61131-3 COMPLIANT
  MODULE:        High-Pressure Hydrocarbon Turret Swivel Joint Sealing and ESD Matrix
  FACILITY:      Offshore Ultra-Deepwater Floating Production Storage and Offloading (FPSO)
  SUBSYSTEM:     Geostationary Turret Internal Weathervaning Swivel Stack Containment Boundary
  DESIGN LIFE:   30 Years Continuous Subsea/Topside Production Service (SIL-3 / IEC 61508 / 61511)

  PHYSICAL SYSTEM DESCRIPTION:
  The turret swivel assembly transfers multi-phase hydrocarbons at pressures up to 520.0 bar
  from sea-floor risers across the 360-degree continuous weathervaning interface to the topside
  separator manifold. The multi-barrier elastomeric/thermoplastic primary and secondary seals
  are dynamically energized by an active synthetic polyalphaolefin (PAO) barrier fluid loop.
  Barrier differential pressure (Delta-P) must be deterministically maintained between 25.0 and
  45.0 bar ABOVE process hydrocarbon line pressure to eliminate outward hydrocarbon migration.

  ADVANCED CONTROL & SAFETY ARCHITECTURE:
  1. Discrete 3rd-Order Luenberger State-Space Observer for inter-seal buffer cavity dynamics.
  2. Receding Horizon Model Predictive Control (MPC) quadratic cost approximation for dynamic
     servo valve modulation under severe vessel roll, pitch, and yaw oscillations.
  3. Triple Modular Redundant (2oo3 TMR) voter with NAMUR NE43 loop health diagnostics and
     deterministic graceful degradation (2oo3 -> 1oo2 -> 1oo1 -> Fail-Safe Trip).
  4. Multi-tiered Cause-and-Effect Emergency Shutdown (ESD) matrix (Levels 0, 1, 2) coupled with
     annular compartment firewater deluge activation.
 ===================================================================================================
*)

VAR_INPUT
    bMasterEnable                   : BOOL;     (* Master functional safety executive permissive [TRUE = Armed] *)
    bSafetyReset                    : BOOL;     (* Manual latched safety reset command from safety console [Pulse] *)
    rProcessGasPressure_bar         : REAL;     (* High-pressure hydrocarbon swivel line process pressure [0.0..550.0 bar] *)
    rCavityPressure_ChA_bar         : REAL;     (* Primary/Secondary buffer seal cavity pressure Ch-A (TMR) [0.0..600.0 bar] *)
    rCavityPressure_ChB_bar         : REAL;     (* Primary/Secondary buffer seal cavity pressure Ch-B (TMR) [0.0..600.0 bar] *)
    rCavityPressure_ChC_bar         : REAL;     (* Primary/Secondary buffer seal cavity pressure Ch-C (TMR) [0.0..600.0 bar] *)
    rTurretGasLEL_ChA_pct           : REAL;     (* Annular swivel compartment optical IR gas detector Ch-A [0.0..100.0 % LEL] *)
    rTurretGasLEL_ChB_pct           : REAL;     (* Annular swivel compartment optical IR gas detector Ch-B [0.0..100.0 % LEL] *)
    rTurretGasLEL_ChC_pct           : REAL;     (* Annular swivel compartment optical IR gas detector Ch-C [0.0..100.0 % LEL] *)
    rBearingTemp_ChA_degC           : REAL;     (* Swivel slew ring & seal face temperature RTD Ch-A [-10.0..150.0 deg C] *)
    rBearingTemp_ChB_degC           : REAL;     (* Swivel slew ring & seal face temperature RTD Ch-B [-10.0..150.0 deg C] *)
    rBearingTemp_ChC_degC           : REAL;     (* Swivel slew ring & seal face temperature RTD Ch-C [-10.0..150.0 deg C] *)
    rBarrierOilFlow_m3h             : REAL;     (* High-pressure barrier fluid recirculation flow rate [0.0..30.0 m3/h] *)
    rBarrierOilTankLevel_pct        : REAL;     (* Skid barrier fluid hydraulic reservoir accumulator level [0.0..100.0 %] *)
    rTurretYawAngle_deg             : REAL;     (* Absolute turret-to-hull weathervane orientation azimuth [0.0..360.0 deg] *)
    rTurretYawRate_deg_s            : REAL;     (* Angular slew rate derived from dual inertial gyro sensors [-10.0..10.0 deg/s] *)
    rAnalogLoopCurrent_mA           : REAL;     (* Diagnostic 4-20mA loop integrity current for electro-hydraulic valve [3.6..21.5 mA] *)
END_VAR

VAR_OUTPUT
    bSwivelOperationalPermissive    : BOOL;     (* Overall system operational permissive status [TRUE = Healthy/Run] *)
    rBarrierPumpPressureSP_bar      : REAL;     (* Optimal pressure setpoint for variable-speed barrier pump [0.0..600.0 bar] *)
    rBarrierControlValve_pct        : REAL;     (* Modulating electro-hydraulic servo valve position command [0.0..100.0 %] *)
    bTripESD_Level1_Depressurize    : BOOL;     (* Cause-and-Effect ESD Level 1: Controlled swivel line depressurize command *)
    bTripESD_Level2_Isolate         : BOOL;     (* Cause-and-Effect ESD Level 2: Subsea SSIV & topside swivel dual isolation *)
    bTripESD_Level0_FPSO_Abandon    : BOOL;     (* Cause-and-Effect ESD Level 0: Total facility emergency shutdown & blowdown *)
    bDelugeActivation               : BOOL;     (* High-velocity water deluge activation for turret swivel compartment *)
    wSwivelSafetyStatusWord         : WORD;     (* 16-bit status word: bitpacked operational states and degradation flags *)
    wAlarmMatrixWord                : WORD;     (* 16-bit alarm word: latched microleak, high gas, thermal trip, sensor faults *)
    rEstimatedSealWearRate_um_h     : REAL;     (* Discrete observer dynamic estimate of PTFE seal lip wear [0.0..500.0 um/h] *)
END_VAR

VAR
    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) ARCHITECTURE --- *)
    bChA_Valid_Press                : BOOL;
    bChB_Valid_Press                : BOOL;
    bChC_Valid_Press                : BOOL;
    rVotedCavityPressure_bar        : REAL;
    bPressTMR_Degraded_1oo2         : BOOL;
    bPressTMR_Critical_1oo1         : BOOL;
    bPressTMR_TotalSensorFailure    : BOOL;

    bChA_Valid_Gas                  : BOOL;
    bChB_Valid_Gas                  : BOOL;
    bChC_Valid_Gas                  : BOOL;
    rVotedGasLEL_pct                : REAL;
    bGasLEL_High_Alarm_20           : BOOL;
    bGasLEL_HighHigh_Trip_60        : BOOL;

    bChA_Valid_Temp                 : BOOL;
    bChB_Valid_Temp                 : BOOL;
    bChC_Valid_Temp                 : BOOL;
    rVotedBearingTemp_degC          : REAL;
    bBearingTemp_High_Alarm_80      : BOOL;
    bBearingTemp_HighHigh_Trip_95   : BOOL;

    (* --- DISCRETE STATE-SPACE OBSERVER MATRICES (3x3 Plant Model) --- *)
    (* State vector x = [x1: Buffer Cavity Pressure (bar), x2: dP/dt Rate (bar/s), x3: Internal Seal Leakage (m3/h)] *)
    aMatrixA                        : ARRAY[1..3, 1..3] OF REAL;
    aMatrixB                        : ARRAY[1..3, 1..1] OF REAL;
    aMatrixC                        : ARRAY[1..1, 1..3] OF REAL;
    aMatrixD                        : ARRAY[1..1, 1..1] OF REAL;
    aStateVectorX                   : ARRAY[1..3] OF REAL;
    aStateVectorX_Next              : ARRAY[1..3] OF REAL;
    aObserverGainL                  : ARRAY[1..3] OF REAL;
    rObserverOutputY                : REAL;
    rObserverInnovation             : REAL;

    (* --- MODEL PREDICTIVE CONTROL (MPC) RECURSIVE QUADRATIC OPTIMIZATION --- *)
    rTargetDifferentialPress_bar    : REAL := 35.0;  (* Desired overpressure: P_barrier - P_process = 35.0 bar *)
    rFilteredProcessPressure_bar    : REAL;
    rIdealBarrierPressureSP_bar     : REAL;
    rPressureError                  : REAL;
    rWeightQ_Tracking               : REAL := 25.0;  (* State error weighting penalty matrix diagonal entry *)
    rWeightR_ActuatorEffort         : REAL := 1.75;  (* Delta-U control rate change penalty factor *)
    rPredictedErrorHorizon          : REAL;
    rControlGradient                : REAL;
    rHessianInverseApprox           : REAL := 0.382; (* Pre-computed unconstrained inverted Hessian term *)
    rOptimalDeltaU                  : REAL;
    rControlOutputAccumulator       : REAL := 0.0;

    (* --- FINITE STATE MACHINE (FSM) & TIMERS --- *)
    iExecutionState                 : INT := 0;      (* Main operational sequencer state register *)
    tonPurgeTimer                   : TON;           (* Flushing / barrier de-aeration timer *)
    tonPressurizationRamp           : TON;           (* Controlled pressure equalization timer *)
    tonDiscrepancyCheck             : TON;           (* Sensor deviation persistence qualification timer *)
    tonMicroLeakDebounce            : TON;           (* Secondary barrier breach integration timer *)
    rCavityDiffOverpressure_bar     : REAL;
    bFirstScanInitialized           : BOOL := FALSE; (* First scan configuration latch *)
    iLoopRow                        : INT;
    iLoopCol                        : INT;
    rMatrixProdAccum                : REAL;
    rTempSortedArray                : ARRAY[1..3] OF REAL;
    rSwapTemp                       : REAL;
END_VAR

(* ===================================================================================================
   SECTION 1: FIRST SCAN ALGORITHMIC INITIALIZATION & STATE-SPACE COEFFICIENTS
   State-Space Representation of Hydraulic Swivel Buffer Cavity:
   dx/dt = A*x + B*u + E*w
   y     = C*x + D*u
   Discrete Euler Formulation at Sample Period Ts = 50ms:
   A = [ 0.9412,  0.0471, -0.0125 ]   B = [ 0.0588 ]
       [ -0.118,  0.8824, -0.0450 ]       [ 0.1176 ]
       [  0.000,  0.0000,  0.9995 ]       [ 0.0000 ]
   C = [ 1.0000,  0.0000,  0.0000 ]   D = [ 0.0000 ]
   Observer Gain L = [ 0.3200, 0.4500, 0.0850 ]^T
   =================================================================================================== *)
IF NOT bFirstScanInitialized THEN
    (* Row 1 *)
    aMatrixA[1, 1] := 0.9412; aMatrixA[1, 2] := 0.0471; aMatrixA[1, 3] := -0.0125;
    (* Row 2 *)
    aMatrixA[2, 1] := -0.1180; aMatrixA[2, 2] := 0.8824; aMatrixA[2, 3] := -0.0450;
    (* Row 3 *)
    aMatrixA[3, 1] := 0.0000; aMatrixA[3, 2] := 0.0000; aMatrixA[3, 3] := 0.9995;

    (* Input Matrix B *)
    aMatrixB[1, 1] := 0.0588;
    aMatrixB[2, 1] := 0.1176;
    aMatrixB[3, 1] := 0.0000;

    (* Output Matrix C *)
    aMatrixC[1, 1] := 1.0000; aMatrixC[1, 2] := 0.0000; aMatrixC[1, 3] := 0.0000;

    (* Direct Feedthrough D *)
    aMatrixD[1, 1] := 0.0000;

    (* Luenberger Observer Innovation Vector L *)
    aObserverGainL[1] := 0.3200;
    aObserverGainL[2] := 0.4500;
    aObserverGainL[3] := 0.0850;

    (* Reset State Estimators *)
    aStateVectorX[1] := 0.0; (* Estimated Buffer Cavity Pressure [bar] *)
    aStateVectorX[2] := 0.0; (* Estimated Rate of Pressure Change [bar/s] *)
    aStateVectorX[3] := 0.0; (* Estimated Micro-Leak Flow Across Primary Boundary [m3/h] *)

    bFirstScanInitialized := TRUE;
END_IF;

(* ===================================================================================================
   SECTION 2: NAMUR NE43 ANALOG DIAGNOSTICS & SENSOR INTEGRITY QUALIFICATION
   Valid 4-20mA operational window defined as 3.80mA to 20.50mA.
   Current below 3.60mA indicates wire break / loop open circuit.
   Current above 21.00mA indicates transducer bridge short circuit.
   =================================================================================================== *)
(* Cavity Pressure Transmitters Diagnostic Qualification *)
bChA_Valid_Press := (rCavityPressure_ChA_bar >= 0.0) AND (rCavityPressure_ChA_bar <= 580.0);
bChB_Valid_Press := (rCavityPressure_ChB_bar >= 0.0) AND (rCavityPressure_ChB_bar <= 580.0);
bChC_Valid_Press := (rCavityPressure_ChC_bar >= 0.0) AND (rCavityPressure_ChC_bar <= 580.0);

(* Optical IR Hydrocarbon Detectors Diagnostic Qualification *)
bChA_Valid_Gas := (rTurretGasLEL_ChA_pct >= 0.0) AND (rTurretGasLEL_ChA_pct <= 100.0);
bChB_Valid_Gas := (rTurretGasLEL_ChB_pct >= 0.0) AND (rTurretGasLEL_ChB_pct <= 100.0);
bChC_Valid_Gas := (rTurretGasLEL_ChC_pct >= 0.0) AND (rTurretGasLEL_ChC_pct <= 100.0);

(* Bearing Race RTD Thermal Probes Diagnostic Qualification *)
bChA_Valid_Temp := (rBearingTemp_ChA_degC >= -5.0) AND (rBearingTemp_ChA_degC <= 140.0);
bChB_Valid_Temp := (rBearingTemp_ChB_degC >= -5.0) AND (rBearingTemp_ChB_degC <= 140.0);
bChC_Valid_Temp := (rBearingTemp_ChC_degC >= -5.0) AND (rBearingTemp_ChC_degC <= 140.0);

(* Valve Actuator Loop Current Diagnostic Check *)
IF (rAnalogLoopCurrent_mA < 3.8) OR (rAnalogLoopCurrent_mA > 20.8) THEN
    wAlarmMatrixWord.%0 := TRUE; (* Bit 0: Electro-Hydraulic Servo Valve Loop Fault *)
ELSE
    wAlarmMatrixWord.%0 := FALSE;
END_IF;

(* ===================================================================================================
   SECTION 3: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & GRACEFUL DEGRADATION
   TMR voting architecture with deterministic median selection under 3-healthy channels.
   Automatic fallback to 1oo2 arithmetic mean with conservative discrepancy trip if 1 channel fails.
   Automatic fallback to 1oo1 degraded mode if 2 channels fail.
   Fail-safe trip initiation if all 3 channels fail qualification.
   =================================================================================================== *)
(* --- 3.1 CAVITY BUFFER PRESSURE VOTING --- *)
IF bChA_Valid_Press AND bChB_Valid_Press AND bChC_Valid_Press THEN
    (* All three healthy: Bubble-sort to extract Median *)
    rTempSortedArray[1] := rCavityPressure_ChA_bar;
    rTempSortedArray[2] := rCavityPressure_ChB_bar;
    rTempSortedArray[3] := rCavityPressure_ChC_bar;

    IF rTempSortedArray[1] > rTempSortedArray[2] THEN
        rSwapTemp := rTempSortedArray[1];
        rTempSortedArray[1] := rTempSortedArray[2];
        rTempSortedArray[2] := rSwapTemp;
    END_IF;
    IF rTempSortedArray[2] > rTempSortedArray[3] THEN
        rSwapTemp := rTempSortedArray[2];
        rTempSortedArray[2] := rTempSortedArray[3];
        rTempSortedArray[3] := rSwapTemp;
    END_IF;
    IF rTempSortedArray[1] > rTempSortedArray[2] THEN
        rSwapTemp := rTempSortedArray[1];
        rTempSortedArray[1] := rTempSortedArray[2];
        rTempSortedArray[2] := rSwapTemp;
    END_IF;

    rVotedCavityPressure_bar := rTempSortedArray[2]; (* Voted Median *)
    bPressTMR_Degraded_1oo2 := FALSE;
    bPressTMR_Critical_1oo1 := FALSE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF (bChA_Valid_Press AND bChB_Valid_Press) THEN
    rVotedCavityPressure_bar := (rCavityPressure_ChA_bar + rCavityPressure_ChB_bar) * 0.5;
    bPressTMR_Degraded_1oo2 := TRUE;
    bPressTMR_Critical_1oo1 := FALSE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF (bChA_Valid_Press AND bChC_Valid_Press) THEN
    rVotedCavityPressure_bar := (rCavityPressure_ChA_bar + rCavityPressure_ChC_bar) * 0.5;
    bPressTMR_Degraded_1oo2 := TRUE;
    bPressTMR_Critical_1oo1 := FALSE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF (bChB_Valid_Press AND bChC_Valid_Press) THEN
    rVotedCavityPressure_bar := (rCavityPressure_ChB_bar + rCavityPressure_ChC_bar) * 0.5;
    bPressTMR_Degraded_1oo2 := TRUE;
    bPressTMR_Critical_1oo1 := FALSE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF bChA_Valid_Press THEN
    rVotedCavityPressure_bar := rCavityPressure_ChA_bar;
    bPressTMR_Degraded_1oo2 := FALSE;
    bPressTMR_Critical_1oo1 := TRUE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF bChB_Valid_Press THEN
    rVotedCavityPressure_bar := rCavityPressure_ChB_bar;
    bPressTMR_Degraded_1oo2 := FALSE;
    bPressTMR_Critical_1oo1 := TRUE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSIF bChC_Valid_Press THEN
    rVotedCavityPressure_bar := rCavityPressure_ChC_bar;
    bPressTMR_Degraded_1oo2 := FALSE;
    bPressTMR_Critical_1oo1 := TRUE;
    bPressTMR_TotalSensorFailure := FALSE;

ELSE
    rVotedCavityPressure_bar := 0.0;
    bPressTMR_Degraded_1oo2 := FALSE;
    bPressTMR_Critical_1oo1 := FALSE;
    bPressTMR_TotalSensorFailure := TRUE;
END_IF;

(* --- 3.2 HYDROCARBON GAS DETECTION 2oo3 VOTING --- *)
IF ( (bChA_Valid_Gas AND rTurretGasLEL_ChA_pct >= 20.0) AND (bChB_Valid_Gas AND rTurretGasLEL_ChB_pct >= 20.0) ) OR
   ( (bChA_Valid_Gas AND rTurretGasLEL_ChA_pct >= 20.0) AND (bChC_Valid_Gas AND rTurretGasLEL_ChC_pct >= 20.0) ) OR
   ( (bChB_Valid_Gas AND rTurretGasLEL_ChB_pct >= 20.0) AND (bChC_Valid_Gas AND rTurretGasLEL_ChC_pct >= 20.0) ) THEN
    bGasLEL_High_Alarm_20 := TRUE;
ELSE
    bGasLEL_High_Alarm_20 := FALSE;
END_IF;

IF ( (bChA_Valid_Gas AND rTurretGasLEL_ChA_pct >= 60.0) AND (bChB_Valid_Gas AND rTurretGasLEL_ChB_pct >= 60.0) ) OR
   ( (bChA_Valid_Gas AND rTurretGasLEL_ChA_pct >= 60.0) AND (bChC_Valid_Gas AND rTurretGasLEL_ChC_pct >= 60.0) ) OR
   ( (bChB_Valid_Gas AND rTurretGasLEL_ChB_pct >= 60.0) AND (bChC_Valid_Gas AND rTurretGasLEL_ChC_pct >= 60.0) ) THEN
    bGasLEL_HighHigh_Trip_60 := TRUE;
ELSE
    bGasLEL_HighHigh_Trip_60 := FALSE;
END_IF;

(* Max LEL calculation for telemetry monitoring *)
rVotedGasLEL_pct := rTurretGasLEL_ChA_pct;
IF rTurretGasLEL_ChB_pct > rVotedGasLEL_pct THEN
    rVotedGasLEL_pct := rTurretGasLEL_ChB_pct;
END_IF;
IF rTurretGasLEL_ChC_pct > rVotedGasLEL_pct THEN
    rVotedGasLEL_pct := rTurretGasLEL_ChC_pct;
END_IF;

(* --- 3.3 BEARING & SEAL FACE TEMPERATURE 2oo3 VOTING --- *)
IF ( (bChA_Valid_Temp AND rBearingTemp_ChA_degC >= 80.0) AND (bChB_Valid_Temp AND rBearingTemp_ChB_degC >= 80.0) ) OR
   ( (bChA_Valid_Temp AND rBearingTemp_ChA_degC >= 80.0) AND (bChC_Valid_Temp AND rBearingTemp_ChC_degC >= 80.0) ) OR
   ( (bChB_Valid_Temp AND rBearingTemp_ChB_degC >= 80.0) AND (bChC_Valid_Temp AND rBearingTemp_ChC_degC >= 80.0) ) THEN
    bBearingTemp_High_Alarm_80 := TRUE;
ELSE
    bBearingTemp_High_Alarm_80 := FALSE;
END_IF;

IF ( (bChA_Valid_Temp AND rBearingTemp_ChA_degC >= 95.0) AND (bChB_Valid_Temp AND rBearingTemp_ChB_degC >= 95.0) ) OR
   ( (bChA_Valid_Temp AND rBearingTemp_ChA_degC >= 95.0) AND (bChC_Valid_Temp AND rBearingTemp_ChC_degC >= 95.0) ) OR
   ( (bChB_Valid_Temp AND rBearingTemp_ChB_degC >= 95.0) AND (bChC_Valid_Temp AND rBearingTemp_ChC_degC >= 95.0) ) THEN
    bBearingTemp_HighHigh_Trip_95 := TRUE;
ELSE
    bBearingTemp_HighHigh_Trip_95 := FALSE;
END_IF;

rVotedBearingTemp_degC := (rBearingTemp_ChA_degC + rBearingTemp_ChB_degC + rBearingTemp_ChC_degC) / 3.0;

(* ===================================================================================================
   SECTION 4: DISCRETE LUENBERGER STATE OBSERVER & DYNAMIC SEAL WEAR RATE ESTIMATION
   Observer Algorithm:
   x_hat[k+1] = A * x_hat[k] + B * u[k] + L * (y[k] - C * x_hat[k])
   Output equation:
   y_hat[k]   = C * x_hat[k]
   Innovation:
   e[k]       = y_measured[k] - y_hat[k]
   =================================================================================================== *)
(* Compute Estimated Output y_hat = C * x *)
rObserverOutputY := aMatrixC[1, 1] * aStateVectorX[1] +
                    aMatrixC[1, 2] * aStateVectorX[2] +
                    aMatrixC[1, 3] * aStateVectorX[3];

(* Innovation: Discrepancy between voted physical pressure and model prediction *)
rObserverInnovation := rVotedCavityPressure_bar - rObserverOutputY;

(* Matrix Update: x_next = A * x + B * u + L * innovation *)
FOR iLoopRow := 1 TO 3 DO
    rMatrixProdAccum := 0.0;
    FOR iLoopCol := 1 TO 3 DO
        rMatrixProdAccum := rMatrixProdAccum + (aMatrixA[iLoopRow, iLoopCol] * aStateVectorX[iLoopCol]);
    END_FOR;

    (* Add Input B * u (u is the actual pressure command to the booster pump) *)
    rMatrixProdAccum := rMatrixProdAccum + (aMatrixB[iLoopRow, 1] * (rBarrierControlValve_pct * 5.5));

    (* Add Observer Correction Vector L * innovation *)
    aStateVectorX_Next[iLoopRow] := rMatrixProdAccum + (aObserverGainL[iLoopRow] * rObserverInnovation);
END_FOR;

(* State Vector Update for Next Execution Cycle *)
aStateVectorX[1] := aStateVectorX_Next[1];
aStateVectorX[2] := aStateVectorX_Next[2];
aStateVectorX[3] := aStateVectorX_Next[3];

(* State 3 corresponds to estimated micro-leakage rate across primary seal face [m3/h].
   Tribological PTFE wear rate model: Wear_Rate [um/h] = k_w * P_diff * |v_slew| + Leak_Component *)
rEstimatedSealWearRate_um_h := (0.145 * ABS(rVotedCavityPressure_bar - rProcessGasPressure_bar) * (ABS(rTurretYawRate_deg_s) + 0.05)) +
                               (ABS(aStateVectorX[3]) * 1250.0);

(* Clamp wear rate to positive engineering domain *)
IF rEstimatedSealWearRate_um_h < 0.0 THEN
    rEstimatedSealWearRate_um_h := 0.0;
ELSIF rEstimatedSealWearRate_um_h > 500.0 THEN
    rEstimatedSealWearRate_um_h := 500.0;
END_IF;

(* ===================================================================================================
   SECTION 5: MODEL PREDICTIVE CONTROL (MPC) RECURSIVE QUADRATIC REGULATION
   Optimization Objective:
   Minimize J(Delta_U) = 0.5 * Q * (P_cavity - P_ideal)^2 + 0.5 * R * (Delta_U)^2
   Subject to constraints:
   0.0% <= ValvePosition <= 100.0%
   -5.0%/scan <= Delta_U <= +5.0%/scan
   =================================================================================================== *)
(* First-order lag digital filtering on process hydrocarbon line pressure *)
rFilteredProcessPressure_bar := (0.85 * rFilteredProcessPressure_bar) + (0.15 * rProcessGasPressure_bar);

(* Dynamic Target Setpoint: Always maintain 35.0 bar positive barrier barrier head *)
rIdealBarrierPressureSP_bar := rFilteredProcessPressure_bar + rTargetDifferentialPress_bar;
rBarrierPumpPressureSP_bar  := rIdealBarrierPressureSP_bar;

(* Cavity differential overpressure evaluation *)
rCavityDiffOverpressure_bar := rVotedCavityPressure_bar - rProcessGasPressure_bar;

(* Closed-loop pressure tracking error *)
rPressureError := rIdealBarrierPressureSP_bar - rVotedCavityPressure_bar;

(* 1-Step Horizon Error Prediction using State Observer derivatives *)
rPredictedErrorHorizon := rPressureError - (aStateVectorX[2] * 0.050);

(* Gradient Computation of Quadratic Cost Function: Grad_J = -Q * Error_Predicted *)
rControlGradient := -1.0 * rWeightQ_Tracking * rPredictedErrorHorizon;

(* Unconstrained Newton-Raphson Optimization Step: Delta_U = - (Hessian^-1) * Gradient *)
rOptimalDeltaU := -1.0 * rHessianInverseApprox * rControlGradient * 0.015;

(* Slew-Rate Limiting: Maximum 4.5% position delta per 50ms scan *)
IF rOptimalDeltaU > 4.5 THEN
    rOptimalDeltaU := 4.5;
ELSIF rOptimalDeltaU < -4.5 THEN
    rOptimalDeltaU := -4.5;
END_IF;

(* Modulating Control Output Integration with Anti-Windup *)
rControlOutputAccumulator := rControlOutputAccumulator + rOptimalDeltaU;

IF rControlOutputAccumulator > 100.0 THEN
    rControlOutputAccumulator := 100.0;
ELSIF rControlOutputAccumulator < 0.0 THEN
    rControlOutputAccumulator := 0.0;
END_IF;

rBarrierControlValve_pct := rControlOutputAccumulator;

(* ===================================================================================================
   SECTION 6: MULTI-STAGE FINITE STATE MACHINE (FSM) SEQUENCER & SAFETY MATRIX
   State 0:  STANDBY_COLD_ISOLATED (Swivel line depressurized, waiting enable)
   State 10: BARRIER_HYDRAULIC_FLUSH (Circulation active, air venting, level check)
   State 20: PRESSURIZATION_RAMP (Ramping barrier differential pressure to +35.0 bar)
   State 30: ACTIVE_WEATHERVANING_NORMAL (Full production active, MPC regulating)
   State 40: LEVEL_1_MICROLEAK_WATCH (Primary seal microleak, automated choke back)
   State 50: LEVEL_2_EMERGENCY_ISOLATION (Double-block and bleed swivel valves isolated)
   State 60: LEVEL_0_CATASTROPHIC_BLOWDOWN (Total turret deluge, flare blowdown)
   State 99: LATCHED_SAFETY_LOCKOUT (Lockout state requiring physical reset)
   =================================================================================================== *)
CASE iExecutionState OF

    0: (* --- STANDBY / COLD DEPRESSURIZED --- *)
        bSwivelOperationalPermissive := FALSE;
        bTripESD_Level1_Depressurize := FALSE;
        bTripESD_Level2_Isolate      := FALSE;
        bTripESD_Level0_FPSO_Abandon := FALSE;
        bDelugeActivation            := FALSE;
        rControlOutputAccumulator    := 0.0;

        tonPurgeTimer(IN := FALSE, PT := T#30S);
        tonPressurizationRamp(IN := FALSE, PT := T#45S);

        IF bMasterEnable AND NOT bPressTMR_TotalSensorFailure THEN
            IF (rBarrierOilTankLevel_pct >= 40.0) AND (rBarrierOilFlow_m3h >= 2.0) THEN
                iExecutionState := 10; (* Proceed to Barrier Flush & De-Aeration *)
            END_IF;
        END_IF;

    10: (* --- BARRIER FLUID CIRCULATION & DE-AERATION --- *)
        bSwivelOperationalPermissive := FALSE;
        tonPurgeTimer(IN := TRUE, PT := T#30S);
        rControlOutputAccumulator := 15.0; (* 15% circulation bypass crack position *)

        (* Abort to Lockout if reservoir oil volume drops critically *)
        IF rBarrierOilTankLevel_pct < 25.0 THEN
            wAlarmMatrixWord.%1 := TRUE; (* Bit 1: Low Hydraulic Reservoir Oil Volume *)
            iExecutionState := 99;
        END_IF;

        IF tonPurgeTimer.Q THEN
            tonPurgeTimer(IN := FALSE);
            iExecutionState := 20; (* Proceed to Pressure Ramp *)
        END_IF;

    20: (* --- BARRIER DIFFERENTIAL PRESSURE RAMPING --- *)
        bSwivelOperationalPermissive := FALSE;
        tonPressurizationRamp(IN := TRUE, PT := T#45S);

        (* Confirm differential pressure exceeds +25.0 bar target *)
        IF (rCavityDiffOverpressure_bar >= 25.0) AND (rCavityDiffOverpressure_bar <= 55.0) THEN
            tonPressurizationRamp(IN := FALSE);
            iExecutionState := 30; (* System healthy: Enter Active Weathervaning *)
        END_IF;

        IF tonPressurizationRamp.Q THEN
            (* Failed to achieve differential barrier pressure within 45 seconds *)
            wAlarmMatrixWord.%2 := TRUE; (* Bit 2: Barrier Pressurization Ramp Timeout *)
            tonPressurizationRamp(IN := FALSE);
            iExecutionState := 50; (* Trip to ESD Level 2 *)
        END_IF;

    30: (* --- ACTIVE ONLINE WEATHERVANING OPERATION --- *)
        bSwivelOperationalPermissive := TRUE;

        (* Check for Primary Seal Degradation / Micro-leakage *)
        IF (aStateVectorX[3] > 0.045) OR (rCavityDiffOverpressure_bar < 18.0) THEN
            iExecutionState := 40; (* Transition to Microleak Degradation Watch *)
        END_IF;

        (* Check for ESD-2 Conditions: Confirmed Secondary Barrier Breach or Bearing Heat *)
        IF (rCavityDiffOverpressure_bar < 5.0) OR bBearingTemp_HighHigh_Trip_95 OR bPressTMR_TotalSensorFailure THEN
            iExecutionState := 50; (* Initiate ESD-2 Swivel Isolation *)
        END_IF;

        (* Check for ESD-0 Catastrophic Condition: High-High Gas Leak in Turret Enclosure *)
        IF bGasLEL_HighHigh_Trip_60 THEN
            iExecutionState := 60; (* Initiate ESD-0 Flare Blowdown & Deluge *)
        END_IF;

    40: (* --- LEVEL 1: SEAL DEGRADATION & AUTOMATED CHOKE-BACK --- *)
        bSwivelOperationalPermissive := FALSE;
        bTripESD_Level1_Depressurize := TRUE;
        wAlarmMatrixWord.%3 := TRUE; (* Bit 3: Primary Swivel Seal Face Micro-Breach *)

        (* If differential pressure collapses completely, escalate to ESD Level 2 *)
        IF (rCavityDiffOverpressure_bar < 8.0) OR bGasLEL_High_Alarm_20 THEN
            iExecutionState := 50;
        END_IF;

        (* If gas concentration reaches explosive runaway, escalate directly to ESD Level 0 *)
        IF bGasLEL_HighHigh_Trip_60 THEN
            iExecutionState := 60;
        END_IF;

    50: (* --- LEVEL 2: DUAL SWIVEL ISOLATION (SSIV & TOPSIDE ESDV) --- *)
        bSwivelOperationalPermissive := FALSE;
        bTripESD_Level1_Depressurize := TRUE;
        bTripESD_Level2_Isolate      := TRUE;
        wAlarmMatrixWord.%4 := TRUE; (* Bit 4: ESD Level 2 Swivel Emergency Isolation Active *)

        (* If flammable vapor cloud develops in turret collar, trigger ESD Level 0 *)
        IF bGasLEL_HighHigh_Trip_60 OR (rBearingTemp_ChA_degC > 120.0) THEN
            iExecutionState := 60;
        END_IF;

        (* Once system is safe and operator issues manual reset, lock out *)
        IF NOT bMasterEnable THEN
            iExecutionState := 99;
        END_IF;

    60: (* --- LEVEL 0: CATASTROPHIC FACILITY BLOWDOWN & TURRET DELUGE --- *)
        bSwivelOperationalPermissive := FALSE;
        bTripESD_Level1_Depressurize := TRUE;
        bTripESD_Level2_Isolate      := TRUE;
        bTripESD_Level0_FPSO_Abandon := TRUE;
        bDelugeActivation            := TRUE; (* Firewater deluge activated immediately *)
        wAlarmMatrixWord.%5 := TRUE; (* Bit 5: ESD Level 0 Annular Deluge Triggered *)

        IF NOT bMasterEnable THEN
            iExecutionState := 99;
        END_IF;

    99: (* --- LATCHED SAFETY LOCKOUT --- *)
        bSwivelOperationalPermissive := FALSE;
        bTripESD_Level1_Depressurize := TRUE;
        bTripESD_Level2_Isolate      := TRUE;
        rControlOutputAccumulator    := 0.0;

        (* Manual Reset Sequence: Master enable armed AND safety reset button depressed *)
        IF bMasterEnable AND bSafetyReset THEN
            IF NOT bGasLEL_HighHigh_Trip_60 AND NOT bBearingTemp_HighHigh_Trip_95 AND NOT bPressTMR_TotalSensorFailure THEN
                wAlarmMatrixWord := 16#0000;
                bTripESD_Level1_Depressurize := FALSE;
                bTripESD_Level2_Isolate      := FALSE;
                bTripESD_Level0_FPSO_Abandon := FALSE;
                bDelugeActivation            := FALSE;
                iExecutionState := 0; (* Return to Standby *)
            END_IF;
        END_IF;

ELSE
    iExecutionState := 99; (* Fail-safe catch-all transition *)
END_CASE;

(* ===================================================================================================
   SECTION 7: PACKED SAFETY STATUS & DIAGNOSTIC WORD COMPOSITION
   Bit 00: Swivel System Armed & Healthy
   Bit 01: Active Weathervaning Mode (State 30)
   Bit 02: Barrier Flush & Ramp Sequencer Running (States 10, 20)
   Bit 03: TMR Pressure Sensor Degraded (1oo2 Mode)
   Bit 04: TMR Pressure Sensor Critical (1oo1 Mode)
   Bit 05: Gas Detection High Pre-Alarm (>20% LEL)
   Bit 06: Bearing Temperature High Pre-Alarm (>80 deg C)
   Bit 07: High PTFE Seal Wear Warning (>150 um/h)
   Bit 08: ESD Level 1 Depressurize Tripped
   Bit 09: ESD Level 2 Isolation Tripped
   Bit 10: ESD Level 0 Catastrophic Deluge Tripped
   Bit 11: Safety Lockout Latch Active (State 99)
   =================================================================================================== *)
wSwivelSafetyStatusWord.%0  := bSwivelOperationalPermissive;
wSwivelSafetyStatusWord.%1  := (iExecutionState = 30);
wSwivelSafetyStatusWord.%2  := (iExecutionState = 10) OR (iExecutionState = 20);
wSwivelSafetyStatusWord.%3  := bPressTMR_Degraded_1oo2;
wSwivelSafetyStatusWord.%4  := bPressTMR_Critical_1oo1;
wSwivelSafetyStatusWord.%5  := bGasLEL_High_Alarm_20;
wSwivelSafetyStatusWord.%6  := bBearingTemp_High_Alarm_80;
wSwivelSafetyStatusWord.%7  := (rEstimatedSealWearRate_um_h > 150.0);
wSwivelSafetyStatusWord.%8  := bTripESD_Level1_Depressurize;
wSwivelSafetyStatusWord.%9  := bTripESD_Level2_Isolate;
wSwivelSafetyStatusWord.%10 := bTripESD_Level0_FPSO_Abandon;
wSwivelSafetyStatusWord.%11 := (iExecutionState = 99);

END_FUNCTION_BLOCK
